/*
 * A025636  Exponent of 2 (value of i) in n-th number of form 2^i*6^j.
 * https://oeis.org/A025636
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) is the exponent of 2 in the n‑th smallest number of the
 *            form 2^i * 6^j (with i,j ≥ 0). The sequence is generated by
 *            traversing all pairs (i,j) in increasing order of 2^(i+j) * 3^j,
 *            which is equivalent to increasing values of log2(2^(i+j) * 3^j)
 *            = (i+j) + j·log2(3). The algorithm uses a binar...
 * Range:     u8 n <= 10000, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include <stdint.h>
#include <stdbool.h>
#include <stdlib.h>
#include <string.h>

/* ---------- internal data structures ---------- */
typedef struct {
    idx_t i;           /* exponent of 2   */
    idx_t j;           /* exponent of 6   */
    double logv;       /* key: (i+j) + j·log2(3) */
} Node;

static bool          initialized   = false;
static Node         *heap          = NULL;
static size_t        heap_cap      = 0;
static size_t        heap_len      = 0;
static bool        **visited       = NULL;   /* visited[i][j] */
static size_t       *visited_cap   = NULL;   /* capacity per row */
static size_t        visited_rows  = 0;
static seq_t        *seq_buf       = NULL;
static size_t        seq_cap       = 0;
static size_t        seq_len       = 0;

/* ---------- constants ---------- */
static const double LOG2_3 = 1.584962500721156;   /* log2(3) */

/* ---------- heap operations ---------- */
static void heap_push(Node n)
{
    if (heap_len == heap_cap) {
        size_t new_cap = heap_cap ? heap_cap * 2 : 8;
        Node *tmp = (Node *)realloc(heap, new_cap * sizeof(Node));
        if (!tmp) abort();
        heap = tmp;
        heap_cap = new_cap;
    }
    size_t pos = heap_len++;
    while (pos > 0) {
        size_t parent = (pos - 1) >> 1;
        if (heap[parent].logv <= n.logv) break;
        heap[pos] = heap[parent];
        pos = parent;
    }
    heap[pos] = n;
}

static Node heap_pop(void)
{
    Node res = heap[0];
    heap_len--;
    if (heap_len == 0) return res;
    Node last = heap[heap_len];
    size_t pos = 0;
    while ((pos << 1) + 1 < heap_len) {
        size_t lc = (pos << 1) + 1;
        size_t rc = lc + 1;
        size_t child = (rc < heap_len && heap[rc].logv < heap[lc].logv) ? rc : lc;
        if (heap[child].logv >= last.logv) break;
        heap[pos] = heap[child];
        pos = child;
    }
    heap[pos] = last;
    return res;
}

/* ---------- visited table management ---------- */
static void ensure_visited_rows(idx_t i)
{
    if (i < visited_rows) return;
    size_t new_cap = visited_rows ? visited_rows << 1 : 8;
    while (new_cap <= (size_t)i) new_cap <<= 1;
    bool **tmp_vis = (bool **)realloc(visited, new_cap * sizeof(bool *));
    size_t *tmp_cap = (size_t *)realloc(visited_cap, new_cap * sizeof(size_t));
    if (!tmp_vis || !tmp_cap) abort();
    visited = tmp_vis;
    visited_cap = tmp_cap;
    for (size_t k = visited_rows; k < new_cap; ++k) {
        visited[k] = NULL;
        visited_cap[k] = 0;
    }
    visited_rows = new_cap;
}

static void ensure_visited_pair(idx_t i, idx_t j)
{
    ensure_visited_rows(i);
    if (!visited[i]) {
        visited[i] = (bool *)calloc(1, sizeof(bool));
        if (!visited[i]) abort();
        visited_cap[i] = 1;
    }
    if (j >= visited_cap[i]) {
        size_t new_cap = j + 1;
        bool *tmp = (bool *)realloc(visited[i], new_cap * sizeof(bool));
        if (!tmp) abort();
        memset(tmp + visited_cap[i], 0, (new_cap - visited_cap[i]) * sizeof(bool));
        visited[i] = tmp;
        visited_cap[i] = new_cap;
    }
}

/* ---------- sequence buffer management ---------- */
static void ensure_seq_cap(void)
{
    if (seq_buf) {
        if (seq_len < seq_cap) return;
        size_t new_cap = seq_cap ? seq_cap << 1 : 16;
        seq_t *tmp = (seq_t *)realloc(seq_buf, new_cap * sizeof(seq_t));
        if (!tmp) abort();
        seq_buf = tmp;
        seq_cap = new_cap;
    } else {
        seq_cap = 16;
        seq_buf = (seq_t *)calloc(seq_cap, sizeof(seq_t));
        if (!seq_buf) abort();
    }
}

/* ---------- main sequence function ---------- */
seq_t a(idx_t n)
{
    if (!initialized) {
        heap_cap = 8;
        heap = (Node *)malloc(heap_cap * sizeof(Node));
        if (!heap) abort();

        visited_rows = 1;
        visited = (bool **)calloc(visited_rows, sizeof(bool *));
        if (!visited) abort();
        visited_cap = (size_t *)calloc(visited_rows, sizeof(size_t));
        if (!visited_cap) abort();

        seq_cap = 16;
        seq_buf = (seq_t *)calloc(seq_cap, sizeof(seq_t));
        if (!seq_buf) abort();

        /* start from (i=0, j=0) */
        ensure_visited_pair(0, 0);
        visited[0][0] = true;
        heap_push((Node){ .i = 0, .j = 0, .logv = 0.0 });

        initialized = true;
    }

    while (seq_len < n) {
        Node cur = heap_pop();

        /* record the exponent of 2 */
        ensure_seq_cap();
        seq_buf[seq_len++] = (seq_t)cur.i;

        /* child 1: multiply by 2 -> (i+1, j) */
        {
            idx_t ni = cur.i + 1;
            idx_t nj = cur.j;
            ensure_visited_pair(ni, nj);
            if (!visited[ni][nj]) {
                visited[ni][nj] = true;
                heap_push((Node){ .i = ni, .j = nj, .logv = cur.logv + 1.0 });
            }
        }

        /* child 2: multiply by 6 -> (i, j+1) */
        {
            idx_t ni = cur.i;
            idx_t nj = cur.j + 1;
            ensure_visited_pair(ni, nj);
            if (!visited[ni][nj]) {
                visited[ni][nj] = true;
                heap_push((Node){ .i = ni, .j = nj, .logv = cur.logv + 1.0 + LOG2_3 });
            }
        }
    }

    return seq_buf[n - 1];
}
